// Audio loudness normalization (lane-audio3, user 2026-11-03 "the sounds sound terrible"): audio/levels.json holds a
// playback gain (dB) and a start trim (s) per downloaded sound, generated by work/audio_levels_build.cjs from the asset
// audit (work/audio_asset_audit.cjs). The runtime multiplies each voice by the gain and starts it at the trim; the
// files are never re-encoded. Before: the 18 standard guns' fire sounds spread 18.9 LU (Frenzy -30.3, Bucky -11.5
// LUFS momentary max) at one flat gain, and every one-shot started at 0 (up to 197 ms of silence before an equip).
'use strict';
const fs=require('fs'),assert=require('assert/strict'),path=require('path');const {make,root}=require('./fake_mix.cjs');
const man=JSON.parse(fs.readFileSync(path.join(root,'audio/manifest.json'),'utf8'));
assert(fs.existsSync(path.join(root,'audio/levels.json')),'audio/levels.json exists');
const L=JSON.parse(fs.readFileSync(path.join(root,'audio/levels.json'),'utf8')).files;
for(const[k,f]of Object.entries(man.files)){assert(L[k],'levels entry for '+k);assert.equal(L[k].sha256,f.sha256,'levels.json is stale for '+k+' (rerun work/audio_asset_audit.cjs + work/audio_levels_build.cjs)');assert(Number.isFinite(L[k].g)&&L[k].g>=-12&&L[k].g<=18,k);assert(L[k].o>=0&&L[k].o<f.duration,k);}
const html=fs.readFileSync(path.join(root,'index.html'),'utf8');assert(/var GA_LEVELS=\{"/.test(html),'index.html inlines the levels table (install_valorant.py)');
const F=make();const voice=()=>{const s=F.rec.sources[F.rec.sources.length-1];return s;};
const level=s=>{const g=s.outs[0];const lin=g.gain.ev.filter(e=>e[0]==='linear'&&e[1]>0);return lin.length?lin[0][1]:g.gain.v;};
const eff=[];for(const w of Object.keys(man.weapons)){const key=man.weapons[w].fire;if(!key||!key.startsWith('standard/'))continue;F.x('gaStop()');const n=F.rec.sources.length;F.x(`SFX.gun(${JSON.stringify(w)})`);assert.equal(F.rec.sources.length,n+1,'own '+w+' shot plays');const s=voice(),lv=level(s)/(s.playbackRate.v||1)**0;eff.push([w,L[key].lufs+20*Math.log10(lv/.65)]);
 assert(Math.abs(s.startArgs[1]-L[key].o)<1e-6,w+' fire starts at its trim '+L[key].o+' s (got '+s.startArgs[1]+')');}
const v=eff.map(e=>e[1]),spread=Math.max(...v)-Math.min(...v);console.log('standard fire loudness at playback: spread '+spread.toFixed(1)+' LU',eff.map(e=>e[0]+' '+e[1].toFixed(1)).join(', '));
assert(eff.length===18&&spread<=6,'own gun loudness spread <= 6 LU (was 18.9 LU at one flat gain): '+spread.toFixed(1));
F.c.held='Shorty';F.x('GA.lastWeapon="Vandal";gaTick()');const eq=F.rec.sources.find(s=>s.buffer&&s.buffer.duration===man.files[man.weapons.Shorty.equip].duration&&s.startArgs);assert(eq&&eq.startArgs[1]>0.19,'Shorty equip skips its 197 ms leading silence');
console.log('audio levels: '+Object.keys(L).length+' sounds normalized, trims applied, fire spread '+spread.toFixed(1)+' LU');
